$_MODULE['<{paypal}prestashop>forbraintreeusers_a58c147220666b9844c3cc90fa8726b3'] = 'Vous pouvez continuer à utiliser Braintree en installant le nouveau module Braintree disponible gratuitement via [a @href1@]addons.prestashop[/a].';
$_MODULE['<{paypal}prestashop>forbraintreeusers_c4e26e9f1ceeeb8fefb7028cf2d2a2e9'] = 'Vous pourrez migrer les paramètres de votre compte et les commandes créées via Braintree lorsque vous aurez installé le nouveau module Braintree.';
$_MODULE['<{paypal}prestashop>forbraintreeusers_b1b3a9e5f00eb52d0b92a977ee82181c'] = 'Nous vous recommandons vivement de désinstaller le module PayPal lorsque vous aurez terminé la migration de vos paramètres Braintree.';
$_MODULE['<{paypal}prestashop>forbraintreeusers_bf51567cd44ed14522f9674cddbbdad3'] = 'Je comprends.[br]Vous souhaitez utiliser PayPal sans Braintree.';
$_MODULE['<{paypal}prestashop>restapiintegrationmessage_29dd52f9530ecb11ec20a10b10590f5b'] = 'Comme nous travaillons constamment sur la sécurité de vos informations, une nouvelle version de l\'authentification de votre compte marchand est disponible à partir de la v5.2.0 du module officiel PayPal.';
$_MODULE['<{paypal}prestashop>restapiintegrationmessage_fbd76d66be64d3cc1bf860039b193db7'] = 'Veuillez noter qu\'il est nécessaire de [b]reconnecter votre compte marchand PayPal[/b] afin de pouvoir continuer à utiliser la solution de paiement PayPal.';
$_MODULE['<{paypal}prestashop>prestashopcheckoutinfo_65316efa7409b87099260ad5e3556708'] = 'Ce module permet à vos clients de payer avec leur compte PayPal. Si vous souhaitez accepter les cartes bancaires et d\'autres modes de paiement en plus de PayPal, nous vous recommandons le module [a @href1@]PrestaShop Checkout[/a].';
$_MODULE['<{paypal}prestashop>unregisteredhooksmessage_8855bfb68164e4dfb070572ac3bf62d5'] = 'Le module ne dispose pas des hooks suivants :';
$_MODULE['<{paypal}prestashop>unregisteredhooksmessage_84bb5767918a71a8d7451f116c681857'] = 'Installez automatiquement les hooks requis';
$_MODULE['<{paypal}prestashop>roundingsettingsmessage_89cf2180690c10af20c8ebc29a1da518'] = 'Vos paramètres d\'arrondi ne sont pas entièrement compatibles avec les exigences de PayPal. Afin d\'éviter que certaines transactions échouent, veuillez changer le mode d\'arrondi de PrestaShop dans [a @href1@]Préférences > Général[/a] en :';
$_MODULE['<{paypal}prestashop>webhookhandler_not_available_63c80e1ae9c339fa7115567a99f18125'] = 'Les webhooks PayPal ne peuvent pas être activés. La raison de l\'erreur est l\'une des suivantes :';
$_MODULE['<{paypal}prestashop>webhookhandler_not_available_44fa8d4bf474c2f482d06446bf9f4cda'] = 'htpasswd activé';
$_MODULE['<{paypal}prestashop>webhookhandler_not_available_a34d8be709574a629908812d1b3304fd'] = 'le protocole https n\'est pas supporté';
