$_MODULE['<{paypal}prestashop>webhookhandler_not_available_49243aedb4e2b2c2eee0cc5b51e52ab7'] = 'paramètres de serveur invalides ou droits d\'accès insuffisants.';
$_MODULE['<{paypal}prestashop>webhookhandler_not_available_6a4c2c1fd1a95e203499f0ec002e2c76'] = 'Veuillez corriger le problème ou contacter [a @href1@]notre équipe d\'assistance[/a].';
$_MODULE['<{paypal}prestashop>webhookhandler_not_available_95166bbd6e215335d114a6d7fda7852b'] = 'Les webhooks ne sont pas utilisés par le module jusqu\'au moment où le problème sera résolu. Veuillez actualiser la page pour vérifier à nouveau l\'état.';
$_MODULE['<{paypal}prestashop>logomessage_7e5c120495d17247348b196adf61be8a'] = 'Si vous utilisez la redirection PayPal Checkout, vous pouvez personnaliser le logo de votre boutique. Le logo peut être modifié via les [a @href1@]paramètres[/a] de votre profil commercial.';
$_MODULE['<{paypal}prestashop>forpaypalplususers_58f9d45a3e079c0585ade6a1f3702c4b'] = 'Vous utilisez le compte marchand allemand. À partir de la v5.0.0 du module PayPal officiel, il est obligatoire d\'utiliser PayPal Plus plutôt que PayPal Express Checkout.';
$_MODULE['<{paypal}prestashop>forpaypalplususers_1d943813b4aedae1adf6a962bf47f23f'] = 'Merci d\'ajouter vos identifiants API REST ci-dessous pour configurer votre compte et continuer de proposer la solution de paiement PayPal à vos clients. [a @href1@]En savoir plus à propos de PayPal Plus[/a].';
$_MODULE['<{paypal}prestashop>shortcut-configuration_43e037d4282ba121bf2f204e2786ef37'] = 'Les [b]paramètres avancés de PayPal Express Checkout[/b] sont ajoutés au module afin de fournir la solution la plus personnalisable possible. Vous pouvez personnaliser les options d\'affichage et les styles des raccourcis PayPal. Ils peuvent être modifiés pour chaque bouton séparément en fonction de leur emplacement. Ces options de personnalisation ne seront affichées que si les raccourcis sont activés au moins pour un emplacement (Page produit / Panier / Étape d\'inscription du tunnel de commande)';
$_MODULE['<{paypal}prestashop>shortcut-configuration_72f56aa8380b0d31423fef7ecd9007e1'] = 'Si certains éléments ajoutés via d\'autres modules sont affichés sur le même hook, vous pouvez gérer la position du module PayPal Official via « Apparence > Positions ». Par défaut, les raccourcis PayPal sont affichés sur votre site Web via le « Hook natif PrestaShop ». Si vous choisissez « Widget PrestaShop », vous pourrez copier le code du widget et l\'insérer où vous le souhaitez dans le template de la page produit.';
$_MODULE['<{paypal}prestashop>shortcut-configuration_ebe803ed571317d95ff3e019224a8456'] = 'Les gens du monde entier nous connaissent pour la couleur or et les recherches le confirment. Des tests approfondis ont permis de déterminer la bonne nuance et la bonne forme qui contribuent à augmenter la conversion. Utilisez-le sur votre site web pour tirer parti de la reconnaissance et de la préférence de PayPal.';
$_MODULE['<{paypal}prestashop>shortcut-configuration_b7b662bba6e3116e7a5fdcfe884966c0'] = 'Si l\'or ne fonctionne pas pour votre site, essayez le bouton bleu de PayPal. Les recherches montrent que les gens savent que c\'est la couleur de notre marque, ce qui donne un halo de confiance et de sécurité à votre expérience.';
$_MODULE['<{paypal}prestashop>shortcut-configuration_b9e4d2f15dbab8b7228079f3062dfaa9'] = 'Si l\'or ou le bleu ne convient pas à la conception ou à l\'esthétique de votre site, essayez les boutons argentés, blancs ou noirs. Comme ces couleurs sont moins capables d\'attirer l\'attention des gens, nous recommandons ces couleurs de boutons comme deuxième alternative.';
$_MODULE['<{paypal}prestashop>cloud-sync_3c4ca39186df8cf2ce31b89f775a03dd'] = 'PrestaShop CloudSync';
$_MODULE['<{paypal}prestashop>cloud-sync_52ccdec1b3a406e5feee894ccccf2e47'] = 'PrestaShop CloudSync permet à PrestaShop de collecter des données non sensibles et non personnelles à partir de votre boutique PrestaShop afin d\'améliorer le module.';
$_MODULE['<{paypal}prestashop>cloud-sync_7f054d133d0b2d9a97bb0445eba43d60'] = 'Cette collecte de données est conforme au RGPD et, en tant que marchand, vous pouvez accepter ou refuser l\'envoi de données.';
$_MODULE['<{paypal}prestashop>cloud-sync_0e9d5e82219e029f26794904b7e0e3c6'] = 'Veuillez noter que si vous acceptez, les modules PrestaShop Account et PrestaShop EventBus seront installés sur votre boutique.';
$_MODULE['<{paypal}prestashop>cloud-sync_77fb80c512a0a1a37f947673cb0b4237'] = 'Cela n\'aura pas d\'impact sur votre activité de paiement et de gestion des commandes.';
$_MODULE['<{paypal}prestashop>cloud-sync_e3fb8113cdc95877d10fc747dfe5f34e'] = 'Les informations suivantes seront partagées avec PrestaShop :';
$_MODULE['<{paypal}prestashop>cloud-sync_745b3c9d7d8efb34b1a3e21edc3a9a63'] = 'info : version de PrestaShop et de PHP';
$_MODULE['<{paypal}prestashop>cloud-sync_e2ca13e6261a701aac6125c620ff8867'] = 'modules : la liste des modules installés sur votre boutique PrestaShop';
$_MODULE['<{paypal}prestashop>cloud-sync_61ee3ec593d6c22fe48c0e2adcc07f4d'] = 'thèmes : le thème installé sur votre boutique PrestaShop';
$_MODULE['<{paypal}prestashop>cloud-sync_a2186209d5a24827c4779bf9527ef351'] = 'devises : les devises installées sur votre boutique PrestaShop';
$_MODULE['<{paypal}prestashop>checkout_96ed9391e080855a6e90f633aadd770e'] = '[b]Action de paiement : Vente :[/b] l\'argent est transféré instantanément du compte de l\'acheteur au compte du vendeur au moment du paiement.';
$_MODULE['<{paypal}prestashop>checkout_c92bc8e271e0659ff1818ac03af330b2'] = '[b]Action de paiement : Autorisation :[/b] Le mode Autorisation est un mode de paiement différé qui nécessite que les fonds soient collectés manuellement lorsque vous transférerez l\'argent. Ce mode est utilisé si vous voulez vous assurer que vous avez la marchandise avant de déposer l\'argent';
$_MODULE['<{paypal}prestashop>checkout_e47696e4ae0a98c566044d1389521ead'] = 'Nous recommandons le mode Autorisation uniquement dans le cas où vous devez vérifier vos stocks/disponibilités avant de confirmer la commande.';
$_MODULE['<{paypal}prestashop>checkout_0cc7b0f75e1d17934f804e3bf4e0fafb'] = 'Le mode Autorisation fonctionne avec les méthodes de paiement suivantes : PayPal et cartes. Il ne fonctionne pas avec le paiement sur facture ni avec d’autres méthodes de paiement locales.';
$_MODULE['<{paypal}prestashop>checkout_76b69d00d737bdbaa69eba90dfb7ff2b'] = 'Le mode In-Context offre un meilleur taux de conversion.';
$_MODULE['<{paypal}prestashop>checkout_97efdc14baa46592b894d8d5056c1355'] = '[b]In-Context :[/b] s\'ouvre dans une fenêtre pop-up, permettant à vos acheteurs de finaliser leur paiement sans quitter votre site Web. Expérience optimisée, moderne et rassurante qui bénéficie des mêmes standards de sécurité que lors d\'une redirection vers le site PayPal.';
$_MODULE['<{paypal}prestashop>checkout_1d1ef975b1f522ba454e93b54690899e'] = '[b]Redirection :[/b] Ce mode ne sera appliqué que pour les paiements éligibles, les autres modes de paiement proposés par le module PayPal seront affichés en mode In-Context.';
$_MODULE['<{paypal}prestashop>checkout_6bfb0d3d55e7d45049403130332706f2'] = 'Les [b]raccourcis PayPal Express Checkout[/b] permettent un paiement plus rapide pour vos acheteurs. PayPal vous fournit automatiquement les informations d\'expédition et de facturation du client.';
$_MODULE['<{paypal}prestashop>checkout_3936cbb386d7f28226b0e8394411922e'] = 'Les [b]consignes du service client[/b] sont un message requis pour utiliser la méthode de paiement sur facture.';
$_MODULE['<{paypal}prestashop>checkout_922a479fca84412288915db03cdfeed1'] = '[b]Présenter les avantages PayPal à vos clients :[/b] vous pouvez augmenter votre taux de conversion en présentant les avantages PayPal à vos clients sur la page de sélection des modes de paiement.';
$_MODULE['<{paypal}prestashop>checkout_e028b0667d313a0f1f687ca774141c4e'] = 'Les raccourcis PayPal permettent un paiement plus rapide pour vos acheteurs. PayPal vous fournit automatiquement les informations de livraison et de facturation du client.';
$_MODULE['<{paypal}prestashop>checkout_ea987630f729079526a44941cbd679ea'] = '[b]Nom de marque[/b] affiché en haut à gauche lors du paiement PayPal : une étiquette qui remplace le nom de l\'entreprise dans le compte PayPal sur les pages PayPal. Si vous utilisez PayPal Checkout, vous pouvez également personnaliser le logo de votre boutique. Le logo peut être modifié via les paramètres de votre profil d\'entreprise.';
$_MODULE['<{paypal}prestashop>account_ddc7d0193fd504bed3166e9b00808ddc'] = 'Comment puis-je me connecter avec mon compte PayPal ?';
$_MODULE['<{paypal}prestashop>account_9a833a55dc65bdb4d51623872b6b827e'] = 'Avant de connecter votre boutique à votre compte PayPal, veuillez sélectionner le mode de connexion. Il existe 2 modes de connexion :';
$_MODULE['<{paypal}prestashop>account_6bcba45471706208cf767644930e9c49'] = '[b]Sandbox[/b] ce mode vous permet un lien factice pour tester le flux entre PrestaShop et PayPal. Vous pouvez tester aussi longtemps que nécessaire. Si vous souhaitez créer un compte, merci d\'utiliser le bouton \'Se connecter ou créer votre compte PayPal\'.';
$_MODULE['<{paypal}prestashop>account_8bf89a8d59a7eaa5110cd5e07473238c'] = '[b]Production[/b] ce mode vous permet de vendre vos produits en ligne et d\'être payé par vos clients. Si vous souhaitez créer un compte, veuillez cliquer sur le bouton \'Se connecter ou créer votre compte PayPal\'.';
$_MODULE['<{paypal}prestashop>account_9acd2e21687b6e875164bb9b2a6d05a0'] = '[b]Note:[/b]  Vous devez passer en mode \'Production\' pour activer votre solution de paiement.';
$_MODULE['<{paypal}prestashop>white-list-ip_02e3913bc006e94bdbcbcf8a5c40d2ea'] = 'Vous pouvez également tester votre module PayPal en mode production. Vous pouvez autoriser l\'accès du module à une liste d\'adresses IP. Saisissez l\'IP dans le champ « Liste des IPs autorisées » pour la durée du test et supprimez-la après validation du test.';
$_MODULE['<{paypal}prestashop>bnpl_238227544a9477263a1c5528d1499b4a'] = 'Le [b]paiement en plusieurs fois[/b] permet aux consommateurs de payer en plusieurs versements (3x ou 4x).';
$_MODULE['<{paypal}prestashop>bnpl_9d7883dc12dd4c8fad713236f9a6e0dd'] = 'Le [b]paiement en plusieurs fois[/b] est l\'une des offres de PayPal incluses dans PayPal Checkout. En proposant « Achetez maintenant, payez plus tard », vous offrez à vos clients plus de flexibilité pour effectuer leurs achats et payer en plusieurs fois, tout en étant payé immédiatement. Vous pouvez trouver plus d\'informations sur le site officiel de PayPal.';
$_MODULE['<{paypal}prestashop>bnpl_b36e8f7ae5d5675abf575c848be91890'] = 'Par défaut, les bannières sont activées pour toutes les pages recommandées. Vous pouvez choisir les types de pages pour promouvoir le paiement « Achetez maintenant, payez plus tard » sur votre site.';
$_MODULE['<{paypal}prestashop>tracking_15a561d4416c96a5c34b800fbafd4743'] = 'Configurez les paramètres de suivi pour demander la protection des marchands PayPal, en deux étapes. Sélectionnez le statut de la commande à partir duquel la commande est traitée par le transporteur. Associez le transporteur PrestaShop au transporteur PayPal.';
$_MODULE['<{paypal}prestashop>order-status_869554ef5f71521029be8b3d8967fd9c'] = 'Personnalisez le statut de vos commandes';
$_MODULE['<{paypal}prestashop>order-status_a5f3640b8fb724a6918bfe0aa381cdc4'] = 'Vous pouvez rembourser les commandes payées via PayPal directement via votre BackOffice PrestaShop. Ici, vous pouvez choisir le statut de la commande qui déclenche le remboursement sur PayPal. Choisissez l\'option « Aucune action » si vous souhaitez modifier le statut de la commande sans déclencher le remboursement automatique sur PayPal.';
$_MODULE['<{paypal}prestashop>order-status_738879f4425908557325b1643ac7ea7a'] = 'Vous pouvez annuler les commandes payées via PayPal directement via votre BackOffice PrestaShop. Ici, vous pouvez choisir le statut de la commande qui déclenche l\'annulation par PayPal d\'une transaction autorisée sur PayPal. Choisissez l\'option « Aucune action » si vous souhaitez modifier le statut de la commande sans déclencher l\'annulation automatique sur PayPal.';
$_MODULE['<{paypal}prestashop>order-status_56355d751c8802f9c6c3ec9427434a24'] = 'Vous utilisez actuellement le mode Autorisation. Cela signifie que vous séparez l\'autorisation de paiement de la capture du paiement autorisé. Pour capturer le paiement autorisé, vous devez changer le statut de la commande en « paiement accepté » (ou en un statut personnalisé avec la même signification). Ici, vous pouvez choisir un statut de commande personnalisé pour accepter la commande et valider les transactions en mode Autorisation.';
$_MODULE['<{paypal}prestashop>order-status_5997f429755ea4236441e6924cfcb03f'] = 'L\'activation des webhooks permet à PayPal de mettre à jour les statuts de vos commandes PrestaShop dès que les états de paiement sont modifiés. Il est nécessaire de s\'assurer que les webhooks sont bien reçus par votre PrestaShop.';
$_MODULE['<{paypal}prestashop>order-status_6e8ac23e4fab1b830a7b4b912dbde77e'] = 'Nous avons parallèlement créé un évènement qui appellera les états de commande chaque heure lorsque vous naviguerez sur votre back office PrestaShop.';
$_MODULE['<{paypal}prestashop>order-status_06102d1968aa1370cdb744b6df793b58'] = 'Autre solution si les webhooks ne passent pas : vous pouvez demander l\'installation d\'une tâche cron sur votre serveur qui assurera la mise à jour de vos statuts de commandes selon les états de paiement PayPal, selon la périodicité que vous souhaitez :';
$_MODULE['<{paypal}prestashop>file_integrity_d5e470b67c3207423fa01a479c8b0e0b'] = 'Intégrité des fichiers';
$_MODULE['<{paypal}prestashop>file_integrity_2d25c72c1b18e562f6654fff8e11711e'] = 'Non disponible';
