$_MODULE['<{paypal}prestashop>file_integrity_f15f01b8606261e9ea2396655a52c1ab'] = 'Fichiers manquants ou mis à jour trouvés';
$_MODULE['<{paypal}prestashop>file_integrity_ee12997d89ccdb26e782f75cac0ec779'] = 'Comparez vos fichiers de module %s avec le package officiel de la même version.';
$_MODULE['<{paypal}prestashop>file_integrity_6d51d5c2403532621fcb5375a4ff3951'] = 'Ces fichiers sont introuvables sur votre serveur, vous devez l\'ajouter :';
